    $('#breedDot').hidden=!current().jobs.some(j=>j.end<=now())&&!S.eggs.some(e=>e.ready<=now());$('#questDot').hidden=!D.quests.some(q=>!S.claimed.includes(q.id)&&questValue(q)>=q.target)&&!D.dailyTasks.some(q=>!S.daily.claimed.includes(q.id)&&S.daily.stats[q.stat]>=q.target);
