  function collect(single=null){const ms=single?S.monsters.filter(m=>m.uid===single):onIsland();let amount=0;for(const m of ms){amount+=Math.floor(m.bank);m.bank-=Math.floor(m.bank);}if(amount<1)return toast('Let your creatures sing for a moment.');give({coins:amount});inc('collects');xp(Math.min(35,1+Math.round(Math.log2(amount+1))));if(now()-S.lastEventCollect>=60000){tokens(1+Math.min(30,Math.floor(Math.sqrt(amount)/100)));S.lastEventCollect=now();}Sound.effect('collect');toast(`Encore! +${fmt(amount)} coins.`);updateHUD();save();}
  function feedCost(m){return Math.round(60*Math.pow(1.64,m.level-1)*(D.byId[m.species].beds));}
  function feed(id){const m=S.monsters.find(m=>m.uid===id);if(!m)return;if(m.level>=25)return toast('This voice is fully grown.');if(m.mission)return toast('This creature is away on an expedition.');if(!afford(feedCost(m),'food'))return;m.level++;inc('feeds');xp(35+m.level*3);tokens(1);Sound.effect('feed');showSelected();updateHUD();if(modal==='creature')renderCreature(id);save();}
