  function questValue(q){if(q.id==='infinity')return S.islands.length===7?S.stats.marathonWins||0:0;if(q.stat==='species')return new Set(S.discovered.map(x=>x.split(':')[0])).size;if(q.stat==='islands')return S.islands.length;if(q.stat==='rares'||q.stat==='epics')return S.discovered.filter(x=>x.endsWith(q.stat==='rares'?':rare':':epic')).length;if(q.stat==='ethereals')return new Set(S.discovered.map(x=>x.split(':')[0]).filter(id=>D.byId[id].elements.includes('Ethereal'))).size;if(q.stat==='titans')return new Set(S.discovered.map(x=>x.split(':')[0]).filter(id=>D.byId[id].elements.includes('Titan'))).size;return S.stats[q.stat]||0;}
