  document.addEventListener('input',e=>{const el=e.target;if(el.dataset.setting){S.settings[el.dataset.setting]=num(el.value,0,2000);$('#'+el.id+'Label').textContent=el.value+'%';Sound.applySettings(S.settings);dirty=true;}if(el.id==='voiceVolume'){const m=S.monsters.find(m=>m.uid===Number(el.dataset.id));if(m){m.volume=num(el.value,0,2000);$('#voiceVolumeLabel').textContent=m.volume+'%';dirty=true;}}});
