  document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();return;}if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)){if(e.key==='Enter'&&e.target.id==='chatInput')chatSend();if(e.key==='Enter'&&e.target.id==='redeemCode')redeem();return;}if(modal==='jamLive'&&!e.repeat){const map={a:0,s:1,d:2,ArrowLeft:0,ArrowDown:1,ArrowRight:2};if(map[e.key]!==undefined){e.preventDefault();hitLane(map[e.key]);}}});
