  const canvas=$('#scene'),ctx=canvas.getContext('2d'),groundCache=new Map(),imageCache=new Map();
  function groundImage(){const id=S.current;if(!groundCache.has(id)){const c=document.createElement('canvas');c.width=1200;c.height=760;Art.ground(c.getContext('2d'),theme(),0);groundCache.set(id,c);}return groundCache.get(id);}
  function cachedSprite(m){const key=m.species+m.rarity+m.skin;if(!imageCache.has(key)){const img=new Image();img.src=Art.sprite(m.species,m.rarity,m.skin);imageCache.set(key,img);}return imageCache.get(key);}
  function baseScale(){return Math.max(layout.w<650?.46:.55,Math.min(layout.w/1180,layout.h/650,1.15));}
  function transforms(){layout.scale=baseScale()*camera.zoom;layout.tx=layout.w/2-600*layout.scale+camera.x*layout.scale;layout.ty=layout.h*.51-389*layout.scale+camera.y*layout.scale;}
  function resize(){const r=canvas.getBoundingClientRect();layout.w=r.width;layout.h=r.height;layout.dpr=Math.min(S?.settings.quality==='low'?1:2,window.devicePixelRatio||1);canvas.width=Math.round(r.width*layout.dpr);canvas.height=Math.round(r.height*layout.dpr);transforms();resizeJam();}
  function paint(t){if(!layout.w||!layout.h)return;ctx.setTransform(layout.dpr,0,0,layout.dpr,0,0);ctx.clearRect(0,0,layout.w,layout.h);const motion=S.settings.reducedMotion?1:t/1000;Art.sky(ctx,theme(),layout.w,layout.h,motion);transforms();
    // Small floating islands create depth behind the playable island.
    for(let i=0;i<3;i++){ctx.save();ctx.globalAlpha=.16;let xx=layout.w*(.13+i*.39),yy=layout.h*(.21+i%2*.49);Art.poly(ctx,[[xx-45,yy],[xx,yy+27],[xx+45,yy]],theme().rock);Art.ellipse(ctx,xx,yy,45,12,theme().grass[1]);ctx.restore();}
    ctx.save();ctx.translate(layout.tx,layout.ty);ctx.scale(layout.scale,layout.scale);Art.ellipse(ctx,610,697,259,34,'#344c5c08');ctx.drawImage(groundImage(),0,0);
    const objects=[...Art.structures.map(b=>({type:'building',y:b.y,b})),...current().decor.map(d=>({type:'decor',y:d.y,d})),...onIsland().map(m=>({type:'monster',y:m.y,m}))].sort((a,b)=>a.y-b.y);let many=onIsland().length>65;
    for(const o of objects){if(o.type==='building'){const b=o.b,i=current();let ready=b.id==='breed'&&i.jobs.some(j=>j.end<=now())||b.id==='nursery'&&S.eggs.some(e=>e.ready<=now())||b.id==='bakery'&&i.bakes.some(j=>j.end<=now())||b.id==='mine'&&i.mineBank>=1||b.id==='expeditions'&&S.missions.some(j=>j.end<=now());Art.building(ctx,b,theme(),motion,ready);}else if(o.type==='decor'){const d=D.decorations.find(d=>d.id===o.d.type);Art.decor(ctx,o.d.type,o.d.x,o.d.y,d.color);}else{const m=o.m,s=D.byId[m.species];if(m.mission)ctx.globalAlpha=.3;const sc=s.elements.includes('Titan')?1.32:1;if(many){let img=cachedSprite(m);if(img.complete)ctx.drawImage(img,m.x-78*sc,m.y-125*sc-Math.sin(motion*2+m.uid)*2,156*sc,143*sc);}else Art.creature(ctx,s,m.x,m.y,sc,motion,soundOn&&!m.muted?Sound.singing(m.species):0,m.rarity,m.skin,selected===m.uid);
        if(m.bank>=rate(m)*60&&!m.mission){Art.ellipse(ctx,m.x+25,m.y-103*sc,7,7,'#e6cc86','#bc9e62');Art.line(ctx,[[m.x+25,m.y-107*sc],[m.x+25,m.y-99*sc]],'#a68a55',1.5);}ctx.globalAlpha=1;}}
    ctx.restore();const haze=ctx.createLinearGradient(0,layout.h*.78,0,layout.h);haze.addColorStop(0,'#dce7d000');haze.addColorStop(1,theme().sky[1]+'45');ctx.fillStyle=haze;ctx.fillRect(0,0,layout.w,layout.h);
  }
  function worldPoint(p){transforms();return {x:(p.x-layout.tx)/layout.scale,y:(p.y-layout.ty)/layout.scale};}
  function pointerPoint(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};}
  function tapWorld(p){const q=worldPoint(p);if(moving){if(!validPosition(q.x,q.y))return toast('Choose open ground away from the buildings.');if(moving.type==='monster'){const m=S.monsters.find(m=>m.uid===moving.id);if(m){m.x=q.x;m.y=q.y;}}else if(moving.type==='moveDecor'){const d=current().decor.find(d=>d.uid===moving.id);if(d){d.x=q.x;d.y=q.y;}}else{current().decor.push({uid:uid(),type:moving.id,x:q.x,y:q.y});inc('decorations');xp(20);}moving=null;$('#placing').hidden=true;$('#guide').hidden=false;dirty=true;save();showSelected();Sound.effect('tap');return;}
    const ms=onIsland().slice().sort((a,b)=>b.y-a.y);const hit=ms.find(m=>Math.abs(q.x-m.x)<(D.byId[m.species].elements.includes('Titan')?57:44)&&q.y<m.y+14&&q.y>m.y-(D.byId[m.species].elements.includes('Titan')?155:112));if(hit){selected=hit.uid;showSelected();Sound.effect('tap');return;}
    const decoration=current().decor.slice().reverse().find(d=>Math.abs(q.x-d.x)<30&&q.y<d.y+10&&q.y>d.y-85);if(decoration)return decorSelected(decoration.uid);
    const b=Art.structures.find(b=>Math.abs(q.x-b.x)<(b.id==='castle'?82:56)&&q.y<b.y+12&&q.y>b.y-(b.id==='castle'?157:111));if(b){({castle:renderStructures,breed:renderBreed,nursery:()=>renderBreed('nursery'),bakery:renderBakery,mine:renderStructures,expeditions:renderExpeditions})[b.id]();return;}selected=null;$('#selected').hidden=true;
  }
  function beginGesture(){const ps=[...pointerMap.values()];gesture={start:ps[0],camera:{...camera},moved:false};if(ps.length>=2){gesture.dist=Math.hypot(ps[0].x-ps[1].x,ps[0].y-ps[1].y);gesture.anchor=worldPoint({x:(ps[0].x+ps[1].x)/2,y:(ps[0].y+ps[1].y)/2});gesture.moved=true;}}
  canvas.addEventListener('pointerdown',e=>{if(!S.started)return;canvas.setPointerCapture(e.pointerId);pointerMap.set(e.pointerId,pointerPoint(e));beginGesture();});
  canvas.addEventListener('pointermove',e=>{if(!pointerMap.has(e.pointerId)||!gesture)return;pointerMap.set(e.pointerId,pointerPoint(e));const ps=[...pointerMap.values()];if(ps.length>=2){if(!gesture.dist)beginGesture();const d=Math.hypot(ps[0].x-ps[1].x,ps[0].y-ps[1].y);camera.zoom=Math.max(.65,Math.min(3,gesture.camera.zoom*d/Math.max(1,gesture.dist)));const sc=baseScale()*camera.zoom,mx=(ps[0].x+ps[1].x)/2,my=(ps[0].y+ps[1].y)/2;camera.x=(mx-layout.w/2)/sc+600-gesture.anchor.x;camera.y=(my-layout.h*.51)/sc+389-gesture.anchor.y;gesture.moved=true;}else{const dx=ps[0].x-gesture.start.x,dy=ps[0].y-gesture.start.y;if(Math.hypot(dx,dy)>7)gesture.moved=true;camera.x=Math.max(-600,Math.min(600,gesture.camera.x+dx/layout.scale));camera.y=Math.max(-350,Math.min(350,gesture.camera.y+dy/layout.scale));}});
  canvas.addEventListener('pointerup',e=>{const p=pointerPoint(e),click=pointerMap.size===1&&gesture&&!gesture.moved;pointerMap.delete(e.pointerId);if(click)tapWorld(p);if(pointerMap.size){beginGesture();gesture.moved=true;}else gesture=null;});
