  function updateTimers(){document.querySelectorAll('[data-end]').forEach(el=>el.textContent=el.dataset.end<=now()?'Ready':D.duration((el.dataset.end-now())/1000));document.querySelectorAll('[data-ready]').forEach(el=>{const ready=Number(el.dataset.ready)<=now();el.disabled=!ready;el.textContent=ready?'Hatch on this island':D.duration((el.dataset.ready-now())/1000);});document.querySelectorAll('[data-finish]').forEach(el=>{const ready=Number(el.dataset.finish)<=now();el.disabled=!ready;el.textContent=el.dataset.action==='finishBreed'?(ready?'Move to nursery':'Growing'):el.dataset.action==='harvestBake'?(ready?'Harvest':'Baking'):(ready?'Welcome home':'Exploring');});}
  function tick(){const t=now(),elapsed=(t-lastTick)/1000;lastTick=t;advance(elapsed);if(S.daily.day!==day()){S.daily={day:day(),stats:blankStats(),claimed:[]};dirty=true;}updateHUD();updateTimers();if(t-lastSave>10000)save();if(modal==='social'&&!S.session.private&&t>chatNext){chatNext=t+22000+Math.random()*10000;messages.push(botReply());messages=messages.slice(-80);const log=$('#chatLog');if(log){const div=document.createElement('div');div.className='chat-line';const m=messages[messages.length-1];div.innerHTML='<b>'+esc(m.name)+'</b>'+esc(m.text);log.append(div);log.scrollTop=log.scrollHeight;}}}
