  window.addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>{if(document.hidden){if(S.jam&&!S.jam.paused){pauseJam();if(modal==='jamLive')renderJam();}save(true);}else{const t=now();advance((t-lastTick)/1000);lastTick=t;updateHUD();}});window.addEventListener('pagehide',()=>{if(S.jam)S.jam.paused=true;save(true);});
  S=load();const offline=Math.min(43200,Math.max(0,(now()-S.lastSeen)/1000));if(S.started&&offline>60){const before=S.monsters.reduce((n,m)=>n+m.bank,0);advance(offline);const earned=S.monsters.reduce((n,m)=>n+m.bank,0)-before;setTimeout(()=>toast(`Your choir earned ${fmt(earned)} coins while you were away.`,'gold'),1600);}lastTick=now();Sound.setBand(()=>({island:theme(),monsters:onIsland().filter(m=>!m.mission)}));Sound.applySettings(S.settings);fillIcons();updateHUD();$('#intro').hidden=S.started;$('#nameInput').value=S.name==='Maestro'?'':S.name;resize();setInterval(tick,1000);requestAnimationFrame(frame);
